<!doctype html><html><head><meta charset="utf-8"><style>
@page{margin:28px 36px}body{font-family:DejaVu Sans,sans-serif;color:#26384d;font-size:10px}h1{margin:0;color:#173f75;font-size:19px}.head{display:flex;justify-content:space-between;border-bottom:3px solid #173f75;padding-bottom:10px}.doc{text-align:right}.doc strong{display:block;color:#173f75;font-size:12px}.statement{margin-top:18px;border:1px solid #ccd6e0}.section{padding:7px 10px;background:#eaf0f7;color:#173f75;font-weight:bold;text-transform:uppercase}.line{display:flex;justify-content:space-between;padding:7px 10px;border-top:1px solid #e1e6ec}.line b{font-variant-numeric:tabular-nums}.minus b{color:#b32d3a}.subtotal{background:#f7f9fc;font-weight:bold}.gross{background:#eaf6ef;color:#176940;font-size:11px;font-weight:bold}.net{background:#173f75;color:#fff;font-size:13px;font-weight:bold}.metrics{width:100%;margin-top:14px;border-collapse:separate;border-spacing:6px}.metrics td{padding:9px;border:1px solid #d7e0e9;background:#f7f9fc;text-align:center}.metrics small{display:block;color:#718096}.metrics b{display:block;margin-top:3px;color:#213b5b;font-size:11px}.note{margin-top:13px;padding:8px;border:1px solid #d8e1eb;background:#f8fafc;color:#66778b;font-size:8px}
</style></head><body>
<div class="head"><div><h1>Laporan Laba Rugi</h1><span>{{ $from->format('d/m/Y') }} s.d. {{ $to->format('d/m/Y') }}</span></div><div class="doc"><strong>{{ config('app.name') }}</strong><span>Dicetak {{ now()->format('d/m/Y H:i') }}</span></div></div>
<div class="statement"><div class="section">Pendapatan</div><div class="line"><span>Subtotal item</span><b>Rp {{ number_format($data['sales_subtotal'],0,',','.') }}</b></div><div class="line minus"><span>Diskon penjualan</span><b>(Rp {{ number_format($data['sales_discounts'],0,',','.') }})</b></div><div class="line"><span>Penjualan kotor</span><b>Rp {{ number_format($data['gross_sales'],0,',','.') }}</b></div><div class="line minus"><span>Retur penjualan</span><b>(Rp {{ number_format($data['returns'],0,',','.') }})</b></div><div class="line subtotal"><span>Penjualan bersih</span><b>Rp {{ number_format($data['net_revenue'],0,',','.') }}</b></div><div class="section">Harga Pokok Penjualan</div><div class="line"><span>HPP barang terjual</span><b>Rp {{ number_format($data['sales_cogs'],0,',','.') }}</b></div><div class="line"><span>Pemulihan HPP retur yang direstok</span><b>(Rp {{ number_format($data['returned_cogs'],0,',','.') }})</b></div><div class="line subtotal"><span>HPP bersih</span><b>Rp {{ number_format($data['net_cogs'],0,',','.') }}</b></div><div class="line gross"><span>Laba kotor</span><b>Rp {{ number_format($data['gross_profit'],0,',','.') }}</b></div><div class="line minus"><span>Pengeluaran operasional</span><b>(Rp {{ number_format($data['expenses'],0,',','.') }})</b></div><div class="line net"><span>Estimasi laba bersih</span><b>Rp {{ number_format($data['net_profit'],0,',','.') }}</b></div></div>
<table class="metrics"><tr><td><small>Transaksi</small><b>{{ number_format($data['sales_transactions']) }}</b></td><td><small>Margin Kotor</small><b>{{ number_format($data['gross_margin'],2,',','.') }}%</b></td><td><small>Margin Bersih</small><b>{{ number_format($data['net_margin'],2,',','.') }}%</b></td><td><small>Rata-rata Transaksi</small><b>Rp {{ number_format($data['average_transaction'],0,',','.') }}</b></td></tr></table><div class="note">HPP retur hanya dipulihkan untuk barang yang dikembalikan ke stok. Barang rusak/tidak direstok tetap menjadi beban HPP.</div></body></html>
